def http(port, req):
    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM); s.settimeout(10)
    s.connect(("127.0.0.1", port)); s.sendall(req.encode("ascii"))
    out = b""
    while True:
        b = s.recv(65536)
        if not b:
            break
        out += b
    s.close()
    head, _, body = out.partition(b"\r\n\r\n")
    return head.decode("latin-1"), body
